const orbit = addons.OrbitControls
const loader = new THREE.TextureLoader()
let structure = undefined

const renderer = new THREE.WebGLRenderer();
renderer.setSize( window.innerWidth, window.innerHeight );
document.body.appendChild( renderer.domElement );

function apply_offset(){
  console.log(M.off)
  if (structure){
    Object.values(structure).forEach((cateogry, c_index) => {
      if (!cateogry) return
      cateogry.forEach((el, e_index) => {
        if (!el || !el.position) return

        el.position.x = e_index * M.off.x
        el.position.y = c_index * M.off.y
        el.position.z = e_index * M.off.z
      })
    })
  }
}

eff_on(() => Object.values(M.off), apply_offset )
