/**
@typedef {Object} vec3 
@property {number} vec3.x
@property {number} vec3.y
@property {number} vec3.z

@param {vec3} vec1
@param {vec3} vec2
*/
function eq(vec1, vec2){
  return vec1.x === vec2.x 
    && vec1.y == vec2.y
    && vec1.z == vec2.z
}


function shuffle(arr) {
  return arr.sort(() => Math.random() > .5 ? 1 : -1)

}

